Billing Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(billing_service, "Billing Service") {
    Component(BillingController, "Billing Controller", "REST / gRPC API", "Handles incoming billing requests and routes them from the API Gateway.")
    Component(BillingProcessingService, "Billing Processing Service", "Microservice Business Logic, Java / Go", "Implements domain logic, transactional outbox pattern, CQRS, and financial data consistency.")
    Component(InsuranceIntegrationAdapter, "Insurance Integration Adapter", "HTTPS / HL7 FHIR APIs", "Submits insurance claims to third-party insurance gateways.")
    Component(SecretsManagementClient, "Secrets Management Client", "HTTPS / Vault API", "Retrieves encrypted configurations and secrets from HashiCorp Vault.")
}

Rel(BillingController, BillingProcessingService, "Delegates business logic execution", "Internal")
Rel(BillingProcessingService, InsuranceIntegrationAdapter, "Submits claims", "HTTPS / HL7 FHIR APIs")
Rel(BillingProcessingService, SecretsManagementClient, "Fetches encrypted secrets", "Vault API")

@enduml

Message Broker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(message_broker, "Message Broker") {
    Component(Event_Producer, "Event Producer", "Kafka Producer / RabbitMQ Publisher", "Publishes asynchronous HL7 FHIR payloads and insurance claims from the Patient/EMR and Billing services using TLS 1.3 and SASL/SCRAM ACLs.")
    Component(Event_Consumer, "Event Consumer", "Kafka Consumer / RabbitMQ Subscriber", "Consumes asynchronous events and payloads across services with `patient_id` partitioning.")
    Component(Schema_Registry, "Schema Registry", "Apache Kafka Schema Registry", "Enforces structural validation and serialization schemas for event payloads.")
    Component(Dead_Letter_Queues_DLQs, "Dead Letter Queues (DLQs)", "Kafka / RabbitMQ DLQ Mechanism", "Captures and stores failed or unprocessable event messages for auditing and error handling.")
}

Rel(Event_Producer, Schema_Registry, "Validates event schemas via", "")
Rel(Event_Producer, Event_Consumer, "Streams asynchronous events to", "")
Rel(Event_Consumer, Dead_Letter_Queues_DLQs, "Routes failed messages to", "")
@enduml

HashiCorp Vault.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the HashiCorp Vault container

Container_Boundary(vault_container, "HashiCorp Vault") {
    Component(vault_server, "Vault Server", "HashiCorp Vault / Go", "Centralized secrets management server providing dynamic database credentials, encryption services, and authentication methods.")
    Component(vault_agent_sidecar, "Vault Agent Sidecar", "Vault Agent / Kubernetes Sidecar", "Local caching and template rendering agent using tmpfs volumes to securely fetch and cache encrypted configurations and secrets.")
    Component(vault_policy_and_mount_manager, "Vault Policy and Mount Manager", "Terraform", "Declarative configuration management tool for defining and provisioning Vault policies, secret engines, and authentication mounts.")
}

Rel(vault_agent_sidecar, vault_server, "Authenticates and fetches secrets via Kubernetes Auth Method and HTTPS", "HTTPS / Vault Agent API")
Rel(vault_policy_and_mount_manager, vault_server, "Configures policies and mounts declaratively", "Terraform / API")

@enduml

Observability & Security Sidecars.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component Diagram for Observability & Security Sidecars

Container_Boundary(observability_security_sidecars, "Observability & Security Sidecars") {
    Component(OpenTelemetry_Collector_Sidecar, "OpenTelemetry Collector Sidecar", "OpenTelemetry", "Collects traces and metrics asynchronously via local Unix domain sockets.")
    Component(Envoy_Proxy_Sidecar, "Envoy Proxy Sidecar", "Envoy", "Handles internal microservice communication via gRPC and REST with mTLS.")
    Component(Falco_Trivy_DaemonSets, "Falco & Trivy DaemonSets", "Falco & Trivy", "Performs node-level runtime security and vulnerability scanning.")
}

Rel(OpenTelemetry_Collector_Sidecar, Envoy_Proxy_Sidecar, "Monitors and intercepts telemetry data from proxy operations.")
Rel(Envoy_Proxy_Sidecar, Falco_Trivy_DaemonSets, "Coordinates with node security agents for secure traffic routing.")

@enduml
